example.code:
h2 + p {
  margin-top: 0;
}

li + li {
  border-top: 1px solid #e2e8f0;
}

article :is(h1, h2, h3) {
  margin-top: 2rem;
}

:where(ul, ol) {
  padding: 0;
}

li:not(:last-child) {
  margin-bottom: 0.5rem;
}

button:hover {
  background: #1e3a8a;
}

button:focus-visible {
  outline: 3px solid #f59e0b;
  outline-offset: 2px;
}

.external::after {
  content: " \2197";
}

.divider::before {
  content: "";
  display: block;
  height: 1px;
  background: #cbd5e1;
}

li::marker {
  color: #1d4ed8;
}

p::first-letter {
  font-size: 2em;
  float: left;
}

a { color: #1d4ed8; }
.overlay { background: rgb(0 0 0 / 60%); }
.badge { background: hsl(220 80% 96%); }

@font-face {
  font-family: "Inter";
  src: url("../fonts/inter.woff2") format("woff2");
  font-weight: 100 900;
  font-display: swap;
}

.card { position: relative; }
.badge {
  position: absolute;
  top: -8px;
  right: -8px;
}
.toc {
  position: sticky;
  top: 1rem;
}

.hero {
  display: flex;
  justify-content: center;
  align-items: center;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  gap: 1rem;
}

.page {
  display: grid;
  grid-template-columns: 14rem 1fr;
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
}
header { grid-area: header; }

button {
  transition: background-color 200ms ease-out, transform 200ms ease-out;
}
button:hover {
  transform: translateY(-2px);
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.spinner {
  animation: spin 1s linear infinite;
}

:root {
  --brand: #1d4ed8;
  --space: 1rem;
}

.card {
  --brand: #be123c;      /* overrides for this component */
  border: 1px solid var(--brand);
  padding: calc(var(--space) * 1.5);
}

button {
  font: inherit;
}

@layer base {
  a { color: #1d4ed8; }
}
